"use client"
const STORAGE_KEY = "chakra-tour-dont-show-again"

const isHidden = () => {
  try {
    return localStorage.getItem(STORAGE_KEY) === "true"
  } catch {
    return false
  }
}

const setHidden = (value: boolean) => {
  try {
    if (value) localStorage.setItem(STORAGE_KEY, "true")
    else localStorage.removeItem(STORAGE_KEY)
  } catch {}
}

export const TourDontShowAgain = () => {
  const [hidden, setHiddenState] = useState(false)
  const dontShowRef = useRef(false)
  const [dontShow, setDontShow] = useState(false)

  useEffect(() => setHiddenState(isHidden()), [])

  const tour = useTour({
    steps,
    onStatusChange({ status }) {
      if (status === "dismissed" || status === "completed") {
        setHidden(dontShowRef.current)
        setHiddenState(dontShowRef.current)
      }
    },
  })

  const openApp = () => {
    if (isHidden()) return
    tour.start()
  }

  return (
    <Stack gap="4">
      <HStack gap="3">
        <Button size="sm" onClick={openApp}>
          Open app
        </Button>
        {hidden && (
          <Button
            size="sm"
            variant="ghost"
            onClick={() => {
              setHidden(false)
              setHiddenState(false)
            }}
          >
            Reset
          </Button>
        )}
      </HStack>

      <Text textStyle="sm" color="fg.muted">
        {hidden
          ? "The welcome tour won't open again until you reset it."
          : "Opening the app shows the welcome tour."}
      </Text>

      <Tour tour={tour}>
        <Checkbox.Root
          size="sm"
          mt="2"
          checked={dontShow}
          onCheckedChange={(e) => {
            dontShowRef.current = !!e.checked
            setDontShow(!!e.checked)
          }}
        >
          <Checkbox.HiddenInput />
          <Checkbox.Control />
          <Checkbox.Label>Don't show this again</Checkbox.Label>
        </Checkbox.Root>
      </Tour>
    </Stack>
  )
}

const steps: TourStep[] = [
  {
    id: "welcome",
    type: "dialog",
    title: "Welcome back",
    description: "Here's what changed since your last visit.",
    actions: [{ label: "Got it", action: "dismiss" }],
  },
]

"use client"
export const TourEmptyState = () => {
  const [projects, setProjects] = useState<string[]>([])
  const tour = useTour({ steps })

  const createProject = () =>
    setProjects((prev) => [...prev, `Project ${prev.length + 1}`])

  return (
    <Stack gap="4" maxW="md" w="full">
      {projects.length === 0 ? (
        <EmptyState.Root borderWidth="1px" rounded="l3">
          <EmptyState.Content>
            <EmptyState.Indicator>
              <LuFolderPlus />
            </EmptyState.Indicator>
            <VStack textAlign="center">
              <EmptyState.Title>No projects yet</EmptyState.Title>
              <EmptyState.Description>
                Projects keep your files and teammates in one place.
              </EmptyState.Description>
            </VStack>
            <HStack>
              <Button id="empty-create" size="sm" onClick={createProject}>
                Create project
              </Button>
              <Button size="sm" variant="outline" onClick={() => tour.start()}>
                Show me how
              </Button>
            </HStack>
          </EmptyState.Content>
        </EmptyState.Root>
      ) : (
        <Stack gap="2">
          {projects.map((name, index) => (
            <Text
              key={name}
              id={index === 0 ? "first-project" : undefined}
              borderWidth="1px"
              rounded="l2"
              px="3"
              py="2"
            >
              {name}
            </Text>
          ))}
          <Button
            size="sm"
            variant="ghost"
            alignSelf="flex-start"
            onClick={() => setProjects([])}
          >
            Reset
          </Button>
        </Stack>
      )}

      <Tour tour={tour} />
    </Stack>
  )
}

const steps: TourStep[] = [
  {
    id: "create",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#empty-create"),
    title: "Create your first project",
    description: "Click the button to make one.",
    effect({ next, show, target }) {
      show()
      const [promise, cancel] = waitForEvent(target, "click")
      promise.then(next)
      return cancel
    },
  },
  {
    id: "project",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#first-project"),
    title: "There it is",
    description: "Open a project to add files and invite teammates.",
    effect({ show }) {
      const [promise, cancel] = waitForElement(
        () => document.querySelector<HTMLElement>("#first-project"),
        { timeout: 3000 },
      )
      promise.then(show)
      return cancel
    },
    actions: [{ label: "Done", action: "dismiss" }],
  },
]

"use client"
const STORAGE_KEY = "chakra-tour-persisted-step"

const read = () => {
  try {
    return localStorage.getItem(STORAGE_KEY)
  } catch {
    return null
  }
}

const write = (stepId: string | null) => {
  try {
    if (stepId) localStorage.setItem(STORAGE_KEY, stepId)
    else localStorage.removeItem(STORAGE_KEY)
  } catch {}
}

export const TourPersisted = () => {
  const [savedStep, setSavedStep] = useState<string | null>(null)

  useEffect(() => setSavedStep(read()), [])

  const tour = useTour({
    steps,
    onStepChange({ stepId }) {
      write(stepId)
      setSavedStep(stepId)
    },
    onStatusChange({ status }) {
      if (status === "completed") {
        write(null)
        setSavedStep(null)
      }
    },
  })

  return (
    <Stack gap="4">
      <HStack gap="3">
        <Button size="sm" onClick={() => tour.start(savedStep ?? undefined)}>
          {savedStep ? "Resume tour" : "Start tour"}
        </Button>
        {savedStep && (
          <Text textStyle="sm" color="fg.muted">
            Saved at step "{savedStep}". Close the tour or reload the page, then
            resume.
          </Text>
        )}
      </HStack>

      <HStack gap="3">
        <Button id="persisted-files" variant="outline" size="sm">
          Files
        </Button>
        <Button id="persisted-share" variant="outline" size="sm">
          Share
        </Button>
        <Button id="persisted-settings" variant="outline" size="sm">
          Settings
        </Button>
      </HStack>

      <Tour tour={tour} />
    </Stack>
  )
}

const steps: TourStep[] = [
  {
    id: "files",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#persisted-files"),
    title: "Files",
    description: "Everything you upload lives here.",
    actions: [{ label: "Next", action: "next" }],
  },
  {
    id: "share",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#persisted-share"),
    title: "Share",
    description: "Send a link to anyone on your team.",
    actions: [
      { label: "Previous", action: "prev" },
      { label: "Next", action: "next" },
    ],
  },
  {
    id: "settings",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#persisted-settings"),
    title: "Settings",
    description: "Finishing the tour clears the saved step.",
    actions: [
      { label: "Previous", action: "prev" },
      { label: "Finish", action: "dismiss" },
    ],
  },
]

"use client"
export const TourWaitForAction = () => {
  const tour = useTour({ steps })

  return (
    <Stack gap="4" maxW="sm">
      <Button size="sm" alignSelf="flex-start" onClick={() => tour.start()}>
        Start Tour
      </Button>

      <Field.Root>
        <Field.Label>Workspace name</Field.Label>
        <Input id="workspace-name" placeholder="Type acme" />
      </Field.Root>

      <Button id="create-workspace" variant="outline" alignSelf="flex-start">
        Create workspace
      </Button>

      <Tour tour={tour} />
    </Stack>
  )
}

const steps: TourStep[] = [
  {
    id: "name",
    type: "tooltip",
    target: () => document.querySelector<HTMLInputElement>("#workspace-name"),
    title: "Name your workspace",
    description: 'Type "acme" to continue.',
    effect({ next, show }) {
      show()
      const [promise, cancel] = waitForElementValue(
        () => document.querySelector<HTMLInputElement>("#workspace-name"),
        "acme",
        { timeout: 60_000 },
      )
      promise.then(next)
      return cancel
    },
  },
  {
    id: "create",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#create-workspace"),
    title: "Create it",
    description: "Click the button to finish.",
    effect({ next, show, target }) {
      show()
      const [promise, cancel] = waitForEvent(target, "click")
      promise.then(next)
      return cancel
    },
  },
  {
    id: "done",
    type: "dialog",
    title: "You're all set",
    description: "The tour moved on each time you did the thing it asked for.",
    actions: [{ label: "Done", action: "dismiss" }],
  },
]

"use client"
export const TourWithMedia = () => {
  const tour = useTour({ steps })

  return (
    <>
      <Button size="sm" onClick={() => tour.start()}>
        See what's new
      </Button>
      <Tour tour={tour}>
        <StepImage />
      </Tour>
    </>
  )
}

const StepImage = () => {
  const { step } = useTourContext()
  const src = step?.meta?.image
  if (!src) return null
  return (
    <Image
      src={src}
      alt=""
      order="-1"
      aspectRatio="16/9"
      objectFit="cover"
      rounded="l2"
      bg="bg.muted"
      mb="2"
    />
  )
}

const steps: TourStep[] = [
  {
    id: "dashboards",
    type: "dialog",
    title: "New dashboards",
    description: "Pin any chart to a dashboard and share it with your team.",
    meta: {
      image:
        "https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=640&q=80",
    },
    actions: [{ label: "Next", action: "next" }],
  },
  {
    id: "themes",
    type: "dialog",
    title: "Dark mode",
    description: "Switch themes from the settings menu.",
    meta: {
      image:
        "https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=640&q=80",
    },
    actions: [
      { label: "Previous", action: "prev" },
      { label: "Done", action: "dismiss" },
    ],
  },
]

"use client"
export const TourWithRouting = () => (
  <MemoryRouter initialEntries={["/"]}>
    <TourContent />
  </MemoryRouter>
)

const TourContent = () => {
  const navigate = useNavigate()
  const location = useLocation()

  const navigateRef = useRef(navigate)
  navigateRef.current = navigate

  const steps = useMemo<TourStep[]>(
    () =>
      tourSteps.map((step) => ({
        ...step,
        effect: ({ show }) => {
          navigateRef.current(stepToPage[step.id])
          const [promise, cancel] = waitForElement(step.target!, {
            timeout: 3000,
          })
          promise.then(show)
          return cancel
        },
      })),
    [],
  )

  const tour = useTour({ steps })
  const isActive = (path: string) => location.pathname === path

  return (
    <Stack gap="4">
      <HStack gap="2">
        {pages.map((p) => (
          <Button
            key={p.path}
            size="sm"
            variant={isActive(p.path) ? "solid" : "outline"}
            asChild
          >
            <Link to={p.path}>{p.label}</Link>
          </Button>
        ))}
      </HStack>

      <Button
        size="sm"
        variant="outline"
        alignSelf="flex-start"
        onClick={() => tour.start()}
      >
        Start Tour
      </Button>

      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/settings" element={<SettingsPage />} />
        <Route path="/profile" element={<ProfilePage />} />
      </Routes>

      <Tour tour={tour} />
    </Stack>
  )
}

const HomePage = () => (
  <Box id="page-home" p="4" borderWidth="1px" borderRadius="md">
    <Text fontWeight="medium">Home</Text>
    <Text textStyle="sm" color="fg.muted">
      Welcome back! Here is your recent activity.
    </Text>
  </Box>
)

const SettingsPage = () => (
  <Box id="page-settings" p="4" borderWidth="1px" borderRadius="md">
    <Text fontWeight="medium">Settings</Text>
    <Text textStyle="sm" color="fg.muted">
      Configure your notification and privacy preferences.
    </Text>
  </Box>
)

const ProfilePage = () => (
  <Box id="page-profile" p="4" borderWidth="1px" borderRadius="md">
    <Text fontWeight="medium">Profile</Text>
    <Text textStyle="sm" color="fg.muted">
      Your name, email, and avatar settings.
    </Text>
  </Box>
)

const pages = [
  { label: "Home", path: "/" },
  { label: "Settings", path: "/settings" },
  { label: "Profile", path: "/profile" },
]

const stepToPage: Record<string, string> = {
  home: "/",
  settings: "/settings",
  profile: "/profile",
}

const tourSteps: Omit<TourStep, "effect">[] = [
  {
    id: "home",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#page-home"),
    title: "Home Page",
    description: "This is your home page with recent activity.",
    actions: [{ label: "Next", action: "next" }],
  },
  {
    id: "settings",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#page-settings"),
    title: "Settings Page",
    description: "Manage your account preferences here.",
    actions: [
      { label: "Previous", action: "prev" },
      { label: "Next", action: "next" },
    ],
  },
  {
    id: "profile",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#page-profile"),
    title: "Profile Page",
    description: "View and edit your profile information.",
    actions: [
      { label: "Previous", action: "prev" },
      { label: "Done", action: "dismiss" },
    ],
  },
]

"use client"
export const TourWithStepTypes = () => {
  const tour = useTour({ steps })

  return (
    <VStack gap="4" alignItems="flex-start">
      <Button size="sm" onClick={() => tour.start()}>
        Start Tour
      </Button>

      <HStack gap="3">
        <Button id="step-feature" variant="outline" size="sm">
          Feature
        </Button>
        <Button id="step-continue" variant="outline" size="sm">
          Continue
        </Button>
      </HStack>

      {tour.step?.type === "wait" && (
        <Text textStyle="sm" color="fg.muted">
          Click the "Continue" button to proceed...
        </Text>
      )}

      <Tour tour={tour} />
    </VStack>
  )
}

const steps: TourStep[] = [
  {
    id: "intro",
    type: "dialog",
    title: "Dialog Step",
    description:
      "This is a dialog step. It appears in the center and is not attached to any element.",
    actions: [{ label: "Next", action: "next" }],
  },
  {
    id: "tooltip",
    type: "tooltip",
    target: () => document.querySelector<HTMLElement>("#step-feature"),
    title: "Tooltip Step",
    description:
      "This is a tooltip step. It points to a specific element on the page.",
    actions: [
      { label: "Previous", action: "prev" },
      { label: "Next", action: "next" },
    ],
  },
  {
    id: "wait",
    type: "wait",
    title: "Wait Step",
    description: "This step pauses the tour until the user takes an action.",
    effect: ({ next }) => {
      const btn = document.querySelector<HTMLElement>("#step-continue")
      const handler = () => next()
      btn?.addEventListener("click", handler, { once: true })
      return () => btn?.removeEventListener("click", handler)
    },
  },
  {
    id: "floating",
    type: "floating",
    title: "Floating Step",
    description:
      "This is a floating step. It appears in a fixed position without targeting any element.",
    actions: [{ label: "Done", action: "dismiss" }],
  },
]
